        <div class="payload-table-scroll"><table :class="{ wide: isDisney }"><thead><tr><th>项目</th><th>分类</th><th>数量</th><th>单价 RMB</th><template v-if="isDisney"><th>迪士尼英文描述</th><th>客户分区</th><th>报客单价 USD</th><th>Included</th></template><th /></tr></thead><tbody><tr v-for="(row,index) in engineering.materials" :key="index"><td><input v-model="row.item" :disabled="disabled" aria-label="工程材料项目"></td><td><select v-model="row.category" :disabled="disabled"><option value="hardware">五金</option><option value="auxiliary">辅料</option><option value="packaging">包装材料</option></select></td><td><input v-model.number="row.quantity" :disabled="disabled" type="number" min="0" step="0.0001"></td><td><input v-model.number="row.unit_price_rmb" :disabled="disabled" type="number" min="0" step="0.0001"></td><template v-if="isDisney"><td><input v-model="row.disney_description" :disabled="disabled" aria-label="迪士尼外购英文描述"></td><td><select v-model="row.disney_section" :disabled="disabled" aria-label="迪士尼外购分区"><option value="product">Product</option><option value="package">Package</option></select></td><td><input v-model.number="row.disney_unit_price_usd" :disabled="disabled" type="number" min="0" step="0.0001" aria-label="迪士尼外购单价 USD"></td><td><input v-model.number="row.disney_included" :disabled="disabled" type="number" min="0" step="0.0001" aria-label="迪士尼 Included"></td></template><td><button type="button" class="icon" :disabled="disabled" @click="remove(engineering.materials,index)"><Trash2 /></button></td></tr><tr v-if="!engineering.materials.length"><td :colspan="isDisney ? 9 : 5" class="empty">暂无材料明细</td></tr></tbody></table></div>
      </section>
