        <div class="inline-fields"><label><span>模具分摊数量</span><input v-model.number="engineering.amortization_qty" :disabled="disabled" type="number" min="0"></label><label><span>客户模费补贴 USD</span><input v-model.number="engineering.customer_mold_subsidy_usd" :disabled="disabled" type="number" min="0" step="0.0001"></label></div>
        <div class="payload-table-scroll"><table :class="{ wide: isDisney || isDickie || isCaixing, extraWide: isDickie || isCaixing }"><thead><tr><th>模具项目</th><th>数量</th><th>费用 RMB</th><template v-if="isDisney"><th>模号</th><th>Parts</th><th>Resin</th><th>穴数</th><th>每啤件数</th><th>Tool Cost USD</th></template><template v-if="isDickie"><th>Project Name (EN)</th><th>Mold #</th><th>Parts (EN)</th><th>Resin</th><th>Mold Size</th><th>Mold Material</th><th>Cav.</th><th>Up</th><th>Mold Cost HKD</th><th>Remark (EN)</th></template><template v-if="isCaixing"><th>Tool Plan Ref</th><th>内部模价 HKD</th><th>客户模价 HKD</th></template><th /></tr></thead><tbody><tr v-for="(row,index) in engineering.molds" :key="index"><td><input v-model="row.item" :disabled="disabled"></td><td><input v-model.number="row.quantity" :disabled="disabled" type="number" min="0" step="0.0001"></td><td><input v-model.number="row.cost_rmb" :disabled="disabled" type="number" min="0" step="0.0001"></td><template v-if="isDisney"><td><input v-model="row.disney_mold_no" :disabled="disabled" aria-label="迪士尼模号"></td><td><input v-model="row.disney_parts" :disabled="disabled" aria-label="迪士尼模具 Parts"></td><td><input v-model="row.disney_material" :disabled="disabled" aria-label="迪士尼模具 Resin"></td><td><input v-model.number="row.disney_cavities" :disabled="disabled" type="number" min="0" aria-label="迪士尼穴数"></td><td><input v-model.number="row.disney_parts_per_shot" :disabled="disabled" type="number" min="0" aria-label="迪士尼每啤件数"></td><td><input v-model.number="row.disney_tool_cost_usd" :disabled="disabled" type="number" min="0" step="0.01" aria-label="迪士尼模价 USD"></td></template><template v-if="isDickie"><td><input v-model="row.dickie_project_name_en" :disabled="disabled" aria-label="Dickie Project Name"></td><td><input v-model="row.dickie_mold_no" :disabled="disabled" aria-label="Dickie Mold Number"></td><td><input v-model="row.dickie_parts_en" :disabled="disabled" aria-label="Dickie Parts English"></td><td><input v-model="row.dickie_resin" :disabled="disabled" aria-label="Dickie Resin"></td><td><input v-model="row.dickie_mold_size" :disabled="disabled" aria-label="Dickie Mold Size"></td><td><input v-model="row.dickie_mold_material" :disabled="disabled" aria-label="Dickie Mold Material"></td><td><input v-model.number="row.dickie_cavities" :disabled="disabled" type="number" min="0" aria-label="Dickie Cavities"></td><td><input v-model.number="row.dickie_parts_per_shot" :disabled="disabled" type="number" min="0" aria-label="Dickie Parts Per Shot"></td><td><input v-model.number="row.dickie_mold_cost_hkd" :disabled="disabled" type="number" min="0" step="0.01" aria-label="Dickie Mold Cost HKD"></td><td><input v-model="row.dickie_remark_en" :disabled="disabled" aria-label="Dickie Mold Remark English"></td></template><template v-if="isCaixing"><td><input v-model="row.caixing_tool_plan_ref" :disabled="disabled" aria-label="彩星 Tool Plan Ref"></td><td><input v-model.number="row.caixing_mold_cost_hkd" :disabled="disabled" type="number" min="0" step="0.01" aria-label="彩星内部模价"></td><td><input v-model.number="row.caixing_customer_mold_cost_hkd" :disabled="disabled" type="number" min="0" step="0.01" aria-label="彩星客户模价"></td></template><td><button type="button" class="icon" :disabled="disabled" @click="remove(engineering.molds,index)"><Trash2 /></button></td></tr><tr v-if="!engineering.molds.length"><td :colspan="isDickie ? 14 : isDisney ? 10 : isCaixing ? 7 : 4" class="empty">暂无模具明细</td></tr></tbody></table></div>
      </section>
      <section class="payload-block">
        <header><div><strong>纸箱与平卡</strong><span>长度、宽度、高度和每箱数量均须大于 0</span></div><button type="button" :disabled="disabled" @click="addEngineeringCarton"><Plus />新增纸箱</button></header>
        <article v-for="(carton,index) in engineering.cartons" :key="index" class="nested-card"><div class="nested-head"><strong>纸箱 {{ index+1 }}</strong><button type="button" class="icon" :disabled="disabled" @click="remove(engineering.cartons,index)"><Trash2 /></button></div><div class="inline-fields five"><label><span>项目</span><input v-model="carton.item" :disabled="disabled"></label><label><span>长 (in)</span><input v-model.number="carton.length_in" :disabled="disabled" type="number" min="0" step="0.01"></label><label><span>宽 (in)</span><input v-model.number="carton.width_in" :disabled="disabled" type="number" min="0" step="0.01"></label><label><span>高 (in)</span><input v-model.number="carton.height_in" :disabled="disabled" type="number" min="0" step="0.01"></label><label><span>每箱数量</span><input v-model.number="carton.qty_per_carton" :disabled="disabled" type="number" min="0" step="0.01"></label><label v-if="isDisney"><span>迪士尼纸箱单价 USD</span><input v-model.number="carton.disney_unit_price_usd" :disabled="disabled" type="number" min="0" step="0.0001" aria-label="迪士尼纸箱单价 USD"></label></div><div class="subhead"><span>平卡</span><button type="button" :disabled="disabled" @click="addFlatCard(index)"><Plus />新增平卡</button></div><div class="payload-table-scroll"><table><thead><tr><th>长 (in)</th><th>宽 (in)</th><th>数量</th><th /></tr></thead><tbody><tr v-for="(flat,flatIndex) in carton.flat_cards" :key="flatIndex"><td><input v-model.number="flat.length_in" :disabled="disabled" type="number" min="0"></td><td><input v-model.number="flat.width_in" :disabled="disabled" type="number" min="0"></td><td><input v-model.number="flat.quantity" :disabled="disabled" type="number" min="0"></td><td><button type="button" class="icon" :disabled="disabled" @click="remove(carton.flat_cards,flatIndex)"><Trash2 /></button></td></tr></tbody></table></div></article>
      </section>
    </template>

    <template v-else-if="props.code === 'electronic'">
      <section class="payload-block"><header><div><strong>电子零件与子项</strong><span>父项和子项均按用量 × 港币单价计算</span></div><button type="button" :disabled="disabled" @click="addElectronicComponent"><Plus />新增零件</button></header><article v-for="(row,index) in electronic.components" :key="index" class="nested-card"><div class="nested-head"><strong>零件 {{ index+1 }}</strong><button type="button" class="icon" :disabled="disabled" @click="remove(electronic.components,index)"><Trash2 /></button></div><div class="inline-fields"><label><span>零件名称</span><input v-model="row.item" :disabled="disabled"></label><label><span>用量</span><input v-model.number="row.quantity" :disabled="disabled" type="number" min="0" step="0.0001"></label><label><span>单价 HKD</span><input v-model.number="row.unit_price_hkd" :disabled="disabled" type="number" min="0" step="0.0001"></label></div><div class="subhead"><span>绑定子项</span><button type="button" :disabled="disabled" @click="addElectronicChild(index)"><Plus />新增子项</button></div><div class="payload-table-scroll"><table><thead><tr><th>子项</th><th>用量</th><th>单价 HKD</th><th /></tr></thead><tbody><tr v-for="(child,childIndex) in row.children" :key="childIndex"><td><input v-model="child.item" :disabled="disabled"></td><td><input v-model.number="child.quantity" :disabled="disabled" type="number" min="0"></td><td><input v-model.number="child.unit_price_hkd" :disabled="disabled" type="number" min="0"></td><td><button type="button" class="icon" :disabled="disabled" @click="remove(row.children,childIndex)"><Trash2 /></button></td></tr></tbody></table></div></article></section>
