      <section class="payload-block"><header><div><strong>出货场景</strong><span>运输容量、纸箱 CUFT 与每箱数量必须大于 0</span></div><button type="button" :disabled="disabled" @click="addScenario"><Plus />新增场景</button></header><div class="payload-table-scroll"><table class="wide"><thead><tr><th>场景</th><th>容量 CUFT</th><th>运费 HKD</th><th>单箱 CUFT</th><th>每箱数量</th><th>运费占比</th><th>吊柜费占比</th><th>码点</th><th>找数</th><th /></tr></thead><tbody><tr v-for="(row,index) in sales.scenarios" :key="index"><td><input v-model="row.name" :disabled="disabled"></td><td><input v-model.number="row.capacity_cuft" :disabled="disabled" type="number" min="0"></td><td><input v-model.number="row.freight_cost_hkd" :disabled="disabled" type="number" min="0"></td><td><input v-model.number="row.carton_cuft" :disabled="disabled" type="number" min="0"></td><td><input v-model.number="row.qty_per_carton" :disabled="disabled" type="number" min="0"></td><td><input v-model.number="row.freight_share" :disabled="disabled" type="number" min="0" step="0.01"></td><td><input v-model.number="row.lift_share" :disabled="disabled" type="number" min="0" step="0.01"></td><td><input v-model.number="row.markup" :disabled="disabled" type="number" min="0" step="0.01"></td><td><input v-model.number="row.settlement" :disabled="disabled" type="number" min="0" step="0.01"></td><td><button type="button" class="icon" :disabled="disabled" @click="remove(sales.scenarios,index)"><Trash2 /></button></td></tr><tr v-if="!sales.scenarios.length"><td colspan="10" class="empty">暂无出货场景</td></tr></tbody></table></div></section>
